class FinanceControlIntegrationTest {
 static EmbeddedPostgres pg;static JdbcTemplate jdbc;static NamedParameterJdbcTemplate named;static TransactionTemplate tx;
 static FinanceOperationsService ops;static FinanceService claims;static FinanceControlService control;static FinanceBankControlService banks;static FinanceAccountingService accounting;
 static final UUID T=UUID.fromString("10000000-0000-0000-0000-000000000001");static final LocalDate DAY=LocalDate.of(2026,10,24);
 UUID hotel,company,owner,manager,finance,director,leader,cashier,bank,party;
 @BeforeAll static void start()throws Exception{pg=EmbeddedPostgres.builder().start();var ds=pg.getPostgresDatabase();jdbc=new JdbcTemplate(ds);jdbc.execute("create role hotel_ai_os_app nologin nosuperuser nobypassrls");Flyway.configure().dataSource(ds).locations("classpath:db/migration").target("100").load().migrate();named=new NamedParameterJdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));var database=new TenantDatabaseContext(jdbc,true);var access=new AccessPolicy();var mapper=new ObjectMapper().findAndRegisterModules();var audit=new AuditWriter(named,e->{});accounting=new FinanceAccountingService(named,database,access,audit,mapper);ops=new FinanceOperationsService(named,database,access,mapper,audit,accounting);claims=new FinanceService(named,database,access,mapper,audit,accounting);control=new FinanceControlService(named,database,access,claims,ops,accounting);banks=new FinanceBankControlService(named,database,access,ops);}
 @AfterAll static void stop()throws Exception{if(pg!=null)pg.close();}@AfterEach void clear(){TenantContext.clear();}
 @BeforeEach void seed(){hotel=UUID.randomUUID();company=UUID.randomUUID();owner=account();manager=account();finance=account();director=account();leader=account();cashier=account();bank=UUID.randomUUID();party=UUID.randomUUID();jdbc.update("insert into org_unit(id,tenant_id,code,name,unit_type) values(?,?,?,'控制测试门店','HOTEL')",hotel,T,hotel.toString());jdbc.update("insert into finance_company(id,tenant_id,name,tax_number) values(?,?,'控制测试公司',?)",company,T,company.toString().replace("-",""));jdbc.update("insert into finance_store_config(tenant_id,hotel_id,company_id,manager_account_id,finance_account_id,director_account_id,leader_account_id,cashier_account_id,workflow_version,payable_account,enabled) values(?,?,?,?,?,?,?,?,2,'应付款',true)",T,hotel,company,manager,finance,director,leader,cashier);as(owner,"*");call(()->ops.saveBankAccount(new FinanceOperationsModels.BankAccount(bank,hotel,"实际银行账户","0000123456","测试银行",DAY.withDayOfMonth(1),new BigDecimal("10000"))));call(()->ops.saveParty(new FinanceOperationsModels.Party(party,hotel,"真实供应商","SUPPLIER","","测试银行","00009999",0)));}
 @Test void oldCashCannotBypassIndependentReviewAndBatchIsIdempotent(){UUID doc=approved("PAYABLE","100",payable());as(cashier,"finance.pay");assertThatThrownBy(()->call(()->ops.settle(doc,settle(5,"30")))).hasMessageContaining("受控付款");
  var instruction=create(doc,"30",null);as(finance,"finance.review");assertThatThrownBy(()->call(()->control.reviewCash(instruction.id(),new Version(0,"不能自审"),true))).hasMessageContaining("不得自审");as(director,"finance.review");call(()->control.reviewCash(instruction.id(),new Version(0,"真实账户核对"),true));
  as(cashier,"finance.pay");var command=new Batch(UUID.randomUUID(),"BANK-"+UUID.randomUUID(),List.of(instruction.id()));call(()->control.execute(command));call(()->control.execute(command));assertThat(jdbc.queryForObject("select count(*) from fo_action where document_id=? and action='PAYMENT'",Integer.class,doc)).isOne();assertThat(jdbc.queryForObject("select amount from fo_action where document_id=? and action='PAYMENT'",BigDecimal.class,doc)).isEqualByComparingTo("30");assertThat(jdbc.queryForObject("select status from fc_cash_instruction where id=?",String.class,instruction.id())).isEqualTo("EXECUTED");assertThatThrownBy(()->jdbc.update("update fc_cash_batch set amount=0 where id=?",command.requestId())).hasMessageContaining("append-only");}
 @Test void beneficiaryChangesInvalidateApprovedCashInstruction(){UUID doc=approved("PAYABLE","100",payable());var cash=create(doc,"30",null);as(director,"finance.review");call(()->control.reviewCash(cash.id(),new Version(0,"已核对"),true));as(owner,"finance.configure");call(()->ops.saveParty(new FinanceOperationsModels.Party(party,hotel,"真实供应商","SUPPLIER","","测试银行","changed-account",0)));as(cashier,"finance.pay");assertThatThrownBy(()->call(()->control.execute(new Batch(UUID.randomUUID(),"BANK-"+UUID.randomUUID(),List.of(cash.id()))))).hasMessageContaining("账户资料已变化");assertThat(jdbc.queryForObject("select count(*) from fo_action where document_id=? and action='PAYMENT'",Integer.class,doc)).isZero();}
 @Test void batchRollsBackAllRowsWhenOneOverpays(){UUID one=approved("PAYABLE","100",payable()),two=approved("PAYABLE","10",payable());var first=create(one,"30",null);var second=create(two,"11",null);for(var cash:List.of(first,second)){as(director,"finance.review");call(()->control.reviewCash(cash.id(),new Version(0,"账户核对"),true));}as(cashier,"finance.pay");assertThatThrownBy(()->call(()->control.execute(new Batch(UUID.randomUUID(),"BANK-"+UUID.randomUUID(),List.of(first.id(),second.id()))))).hasMessageContaining("超过批准金额");assertThat(jdbc.queryForObject("select count(*) from fo_action where document_id in (?,?) and action='PAYMENT'",Integer.class,one,two)).isZero();assertThat(jdbc.queryForObject("select count(*) from fc_cash_instruction where id in (?,?) and status='APPROVED'",Integer.class,first.id(),second.id())).isEqualTo(2);}
 @Test void publishedWorkflowIsAppliedAndPolicyCannotBeSelfPublishedOrOverlap(){UUID alt=account(),policy=UUID.randomUUID();as(owner,"finance.configure");call(()->control.savePolicy(new Policy(policy,hotel,"WORKFLOW","PAYABLE-LOW","小额审批",DAY.withDayOfMonth(1),null,Map.of("documentType","PAYABLE","minimum","0","maximum","200","reviewerIds",List.of(alt,finance,director,leader),"cashierId",cashier))));assertThatThrownBy(()->call(()->control.publishPolicy(policy,new Version(0,"自发布"),false))).hasMessageContaining("必须不同");as(director,"finance.configure");call(()->control.publishPolicy(policy,new Version(0,"独立发布"),false));as(owner,"finance.submit");UUID doc=draft("PAYABLE","100",payable());call(()->ops.submit(doc,new FinanceOperationsModels.Version(UUID.randomUUID(),0)));assertThat(jdbc.queryForObject("select approval_route->>0 from fo_document where id=?",String.class,doc)).isEqualTo(alt.toString());assertThat(jdbc.queryForObject("select count(*) from fc_event where source_id=? and event='ROUTE_FROZEN'",Integer.class,doc)).isOne();}
 @Test void contractNodeAndRetainageRemainBoundedAfterRevision(){UUID doc=approved("CONTRACT","100",Map.of("contractNumber","TEST-"+UUID.randomUUID(),"startDate","2026-10-01","endDate","2026-12-31","paymentPlan",List.of(Map.of("date","2026-10-01","amount","100","label","一期"))));as(owner,"finance.configure");UUID revision=UUID.randomUUID();call(()->control.contract(doc,new Contract(revision,5,new BigDecimal("100"),new BigDecimal("10"),List.of(new ContractNode("FIRST",DAY,new BigDecimal("90"),false),new ContractNode("RETAIN",DAY.plusDays(1),new BigDecimal("10"),true)),"保留质保金")));as(finance,"finance.review");call(()->control.reviewContract(revision,new Version(0,"合同变更已核对")));var cash=create(doc,"91","FIRST");as(director,"finance.review");call(()->control.reviewCash(cash.id(),new Version(0,"账户核对"),true));as(cashier,"finance.pay");assertThatThrownBy(()->call(()->control.execute(new Batch(UUID.randomUUID(),"BANK-"+UUID.randomUUID(),List.of(cash.id()))))).hasMessageContaining("质保金");}
 @Test void realBankFilePreservesLeadingZeroAndCommitsAtomically(){as(cashier,"finance.pay");UUID request=UUID.randomUUID();var mapping=Map.of("externalId","编号","occurredOn","日期","direction","方向","amount","金额","counterparty","对方","reference","摘要");byte[] file="编号,日期,方向,金额,对方,摘要\n000001,2026-10-24,OUT,30.00,供应商,真实流水\n".getBytes(java.nio.charset.StandardCharsets.UTF_8);var preview=call(()->banks.preview(request,bank,"真实流水.csv",file,mapping));assertThat((List<?>)preview.get("errors")).isEmpty();var command=new ImportCommit(0,preview.get("fileHash").toString());call(()->banks.commit(request,command));call(()->banks.commit(request,command));assertThat(jdbc.queryForObject("select external_id from fo_bank_transaction where bank_account_id=?",String.class,bank)).isEqualTo("000001");assertThat(jdbc.queryForObject("select count(*) from fo_bank_transaction where bank_account_id=?",Integer.class,bank)).isOne();}
 @Test void controlScopeAndAppRoleRejectCrossHotelAndMutation(){UUID doc=approved("PAYABLE","100",payable());var cash=create(doc,"30",null);UUID outsider=account();as(outsider,Set.of(UUID.randomUUID()),"finance.read");assertThatThrownBy(()->call(()->control.cash(cash.id()))).isInstanceOf(RuntimeException.class);as(owner,"*");call(()->{assertThatThrownBy(()->jdbc.update("update fc_event set event='CHANGED' where source_id=?",cash.id())).isInstanceOf(RuntimeException.class);return null;});}
 @Test void staleInstructionCreatorCanVoidOnlyItsFrozenInstructionWithoutGainingSourceRead(){
  UUID doc=approved("PAYABLE","100",payable()),maker=account(),outsider=account(),instruction=UUID.randomUUID();
  as(maker,"finance.configure");call(()->control.createCash(new Cash(instruction,"OPERATION",doc,5,"PAYMENT",new BigDecimal("20"),DAY,bank,party,null,"制单原依据","独立于业务审批路线的资金制单")));
  var other=create(doc,"30",null);as(director,"finance.review");call(()->control.reviewCash(other.id(),new Version(0,"核对真实付款"),true));as(cashier,"finance.pay");call(()->control.execute(new Batch(UUID.randomUUID(),"真实版本推进",List.of(other.id()))));
  as(maker,"finance.review");assertThat(call(()->control.cash(instruction))).containsEntry("sourceCurrent",false);
  assertThat(call(()->claims.todos(0)).get("items").toString()).contains(instruction.toString());
  assertThatThrownBy(()->call(()->ops.detail(doc))).isInstanceOf(RuntimeException.class);
  as(outsider,"finance.review");assertThatThrownBy(()->call(()->control.cash(instruction))).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->call(()->control.voidCash(instruction,new Version(0,"不得处置他人指令")))).isInstanceOf(RuntimeException.class);
  as(maker,"finance.review");assertThat(call(()->control.voidCash(instruction,new Version(0,"来源已发生真实付款，作废旧版本未执行指令")))).containsEntry("status","VOID");
  assertThatThrownBy(()->call(()->ops.detail(doc))).isInstanceOf(RuntimeException.class);
 }
 @Test void nonOverlappingFutureDelegationsAreAllFrozenButOnlyActiveWindowCanReview(){
  UUID active=authorizedDeputy(),future=authorizedDeputy(),later=authorizedDeputy();var now=java.time.OffsetDateTime.now().withNano(0);var auth=authorization();
  UUID first=delegation(auth,active,now.minusMinutes(1),now.plusDays(1));delegation(auth,future,now.plusDays(2),now.plusDays(3));delegation(auth,later,now.plusDays(4),now.plusDays(5));
  as(owner,"finance.submit");UUID doc=draft("PAYABLE","100",payable());call(()->ops.submit(doc,new FinanceOperationsModels.Version(UUID.randomUUID(),0)));
  assertThat(jdbc.queryForObject("select count(*) from fd_route where source_id=? and node=0",Integer.class,doc)).isEqualTo(3);
  as(active,"finance.review");assertThat(call(()->ops.detail(doc))).containsEntry("canReview",true);
  as(future,"finance.review");assertThatThrownBy(()->call(()->ops.detail(doc))).isInstanceOf(RuntimeException.class);
  UUID overlapping=UUID.randomUUID();as(owner,"finance.configure");call(()->auth.createDelegation(new FinanceAuthorizationService.Delegation(overlapping,hotel,"OPERATION",manager,future,now.plusHours(2),now.plusDays(2),"重叠不得生效")));as(director,"finance.configure");assertThatThrownBy(()->call(()->auth.publishDelegation(overlapping,new FinanceAuthorizationService.Decision(0,true,"重叠测试"),false))).hasMessageContaining("窗口重叠");
  call(()->auth.publishDelegation(first,new FinanceAuthorizationService.Decision(1,true,"提前撤销当前窗口"),true));as(manager,"finance.review");assertThat(call(()->ops.detail(doc))).containsEntry("canReview",true);
  // The same valid future grants must not prevent the next real document from being submitted.
  as(owner,"finance.submit");UUID next=draft("PAYABLE","10",payable());call(()->ops.submit(next,new FinanceOperationsModels.Version(UUID.randomUUID(),0)));assertThat(jdbc.queryForObject("select count(*) from fd_route where source_id=?",Integer.class,next)).isEqualTo(2);as(manager,"finance.review");assertThat(call(()->ops.detail(next))).containsEntry("canReview",true);
 }
 private UUID delegation(FinanceAuthorizationService auth,UUID deputy,java.time.OffsetDateTime from,java.time.OffsetDateTime until){UUID id=UUID.randomUUID();as(owner,"finance.configure");call(()->auth.createDelegation(new FinanceAuthorizationService.Delegation(id,hotel,"OPERATION",manager,deputy,from,until,"分时段实际代理")));as(director,"finance.configure");call(()->auth.publishDelegation(id,new FinanceAuthorizationService.Decision(0,true,"独立确认不重叠窗口"),false));return id;}
 private UUID authorizedDeputy(){UUID deputy=account();jdbc.update("insert into app_role(tenant_id,code,name,role_type) values(?,'PLATFORM_ADMIN','隔离测试管理员','SYSTEM') on conflict(tenant_id,code) do nothing",T);jdbc.update("insert into role_assignment(tenant_id,account_id,role_id,scope_type) select ?,?,id,'TENANT' from app_role where tenant_id=? and code='PLATFORM_ADMIN'",T,deputy,T);return deputy;}
 private record Created(UUID id){}
 @Test void ledgerChangesNeedRealIndependentPublicationAndQueueIsNotOnlyClaimReview(){
  as(owner,"finance.configure");UUID book=UUID.randomUUID();call(()->accounting.createBook(new FinanceAccountingModels.Book(book,hotel,company,"独立核算",DAY.withDayOfMonth(1))));
  var input=new FinanceAccountingModels.Account(book,"6602","真实成本","EXPENSE","DEBIT","管理费用",false,true,-1);
  assertThatThrownBy(()->call(()->accounting.saveAccount(input))).hasMessageContaining("另一名");
  var governance=new FinanceLedgerGovernance(named,new TenantDatabaseContext(jdbc,true),new AccessPolicy(),accounting);UUID change=UUID.randomUUID();call(()->governance.account(change,input,"真实制度发布"));assertThatThrownBy(()->call(()->governance.publish(change,new Version(0,"自发布"),false))).hasMessageContaining("独立");
  as(director,"finance.configure");var queue=call(()->claims.todos(0));assertThat(((Number)((Map<?,?>)queue.get("counts")).get("review")).intValue()).isGreaterThanOrEqualTo(1);assertThat(queue.get("items").toString()).contains("LEDGER_CHANGE");call(()->governance.publish(change,new Version(0,"独立核对"),false));assertThat(jdbc.queryForObject("select count(*) from fa_account where book_id=? and code='6602'",Integer.class,book)).isOne();
 }
 @Test void currentDraftBudgetExceptionRequiresDirectorAndDoesNotGrantOtherDrafts(){
  UUID policy=UUID.randomUUID();as(owner,"finance.configure");call(()->control.savePolicy(new Policy(policy,hotel,"BUDGET","SUPPLIES-202610","本月费用限额",DAY.withDayOfMonth(1),null,Map.of("month","2026-10","amount","50","control","BLOCK","categoryCode","SUPPLIES","budgetKind","EXPENSE"))));as(director,"finance.configure");call(()->control.publishPolicy(policy,new Version(0,"独立确认预算"),false));
  as(owner,"finance.submit");UUID doc=draft("PAYABLE","100",payable());assertThatThrownBy(()->call(()->ops.submit(doc,new FinanceOperationsModels.Version(UUID.randomUUID(),0)))).hasMessageContaining("预算超额");
  var authorization=authorization();UUID request=UUID.randomUUID();call(()->authorization.requestException(new FinanceAuthorizationService.ExceptionRequest(request,policy,"OPERATION",doc,0,new BigDecimal("100"),java.time.OffsetDateTime.now().plusDays(1),"特殊真实采购")));assertThatThrownBy(()->call(()->authorization.reviewException(request,new FinanceAuthorizationService.Decision(0,true,"本人同意")))).isInstanceOf(RuntimeException.class);
  as(director,"finance.review");call(()->authorization.reviewException(request,new FinanceAuthorizationService.Decision(0,true,"总监核对原草稿限额")));as(owner,"finance.submit");call(()->ops.submit(doc,new FinanceOperationsModels.Version(UUID.randomUUID(),0)));assertThat(jdbc.queryForObject("select state from fc_budget_usage where source_id=?",String.class,doc)).isEqualTo("INFLIGHT");UUID other=draft("PAYABLE","10",payable());assertThatThrownBy(()->call(()->ops.submit(other,new FinanceOperationsModels.Version(UUID.randomUUID(),0)))).hasMessageContaining("预算超额");
 }
 @Test void deputyCurrentNodeWorksAndRevocationRestoresOriginalWithoutChangingRoute(){
  UUID deputy=account();jdbc.update("insert into app_role(tenant_id,code,name,role_type) values(?,'PLATFORM_ADMIN','隔离测试管理员','SYSTEM') on conflict(tenant_id,code) do nothing",T);assertThat(jdbc.update("insert into role_assignment(tenant_id,account_id,role_id,scope_type) select ?,?,id,'TENANT' from app_role where tenant_id=? and code='PLATFORM_ADMIN'",T,deputy,T)).isOne();
  var authorization=authorization();UUID grant=UUID.randomUUID();var start=java.time.OffsetDateTime.now().minusMinutes(1).withNano(0);as(owner,"finance.configure");call(()->authorization.createDelegation(new FinanceAuthorizationService.Delegation(grant,hotel,"OPERATION",manager,deputy,start,start.plusDays(1),"主管短期出差")));assertThatThrownBy(()->call(()->authorization.publishDelegation(grant,new FinanceAuthorizationService.Decision(0,true,"自发布"),false))).hasMessageContaining("独立");as(director,"finance.configure");call(()->authorization.publishDelegation(grant,new FinanceAuthorizationService.Decision(0,true,"独立授权"),false));
  as(owner,"finance.submit");UUID doc=draft("PAYABLE","100",payable());call(()->ops.submit(doc,new FinanceOperationsModels.Version(UUID.randomUUID(),0)));assertThat(jdbc.queryForObject("select approval_route->>0 from fo_document where id=?",String.class,doc)).isEqualTo(manager.toString());as(deputy,"finance.review");assertThat(call(()->ops.detail(doc))).containsEntry("canReview",true);assertThat(call(()->claims.todos(0)).get("items").toString()).contains(doc.toString());as(manager,"finance.review");assertThat(call(()->ops.detail(doc))).containsEntry("canReview",false);
  as(director,"finance.configure");call(()->authorization.publishDelegation(grant,new FinanceAuthorizationService.Decision(1,true,"提前结束代理"),true));as(manager,"finance.review");assertThat(call(()->ops.detail(doc))).containsEntry("canReview",true);as(deputy,"finance.review");assertThatThrownBy(()->call(()->ops.detail(doc))).isInstanceOf(RuntimeException.class);
 }
 @Test void unusedCashCanBeVoidedButExecutedFactsCannotBeVoided(){UUID doc=approved("PAYABLE","100",payable());var cash=create(doc,"30",null);as(finance,"finance.review");call(()->control.voidCash(cash.id(),new Version(0,"收款账户变更，重建指令")));assertThat(jdbc.queryForObject("select status from fc_cash_instruction where id=?",String.class,cash.id())).isEqualTo("VOID");as(director,"finance.review");assertThatThrownBy(()->call(()->control.reviewCash(cash.id(),new Version(1,"不得复活"),true))).isInstanceOf(RuntimeException.class);}
 private FinanceAuthorizationService authorization(){var database=new TenantDatabaseContext(jdbc,true);return new FinanceAuthorizationService(named,database,new AccessPolicy(),new cn.sifangguan.hotelaios.shared.security.EffectiveIdentityService(named,database));}
 private Created create(UUID document,String amount,String node){as(finance,"finance.review");int version=jdbc.queryForObject("select version from fo_document where id=?",Integer.class,document);UUID request=UUID.randomUUID();call(()->control.createCash(new Cash(request,"OPERATION",document,version,"PAYMENT",new BigDecimal(amount),DAY,bank,party,node,"真实流水-"+request,"真实交易核对")));return new Created(request);}
 private UUID draft(String type,String amount,Map<String,Object> details){UUID request=UUID.randomUUID();var doc=new FinanceOperationsModels.Document(request,0,hotel,type,"真实测试业务",DAY,null,party,"MANUAL",null,"本地隔离测试",null,details,List.of(new FinanceOperationsModels.Line("真实业务",BigDecimal.ONE,new BigDecimal(amount),"SUPPLIES",null)));call(()->ops.save(null,doc));return request;}
 private UUID approved(String type,String amount,Map<String,Object> details){as(owner,"finance.submit");UUID doc=draft(type,amount,details);call(()->ops.submit(doc,new FinanceOperationsModels.Version(UUID.randomUUID(),0)));int version=1;for(UUID reviewer:List.of(manager,finance,director,leader)){as(reviewer,"finance.review");int expected=version++;call(()->ops.review(doc,new FinanceOperationsModels.Review(UUID.randomUUID(),expected,"APPROVE","核实通过")));}return doc;}
 private Map<String,Object> payable(){return Map.of("treatment","EXPENSE","orderReference","真实订单","acceptanceReference","真实验收","invoiceReference","真实发票","mismatchNote","");}
 private FinanceOperationsModels.Settlement settle(int version,String amount){return new FinanceOperationsModels.Settlement(UUID.randomUUID(),version,"PAYMENT",new BigDecimal(amount),DAY,bank,null,"BANK-"+UUID.randomUUID(),"",null,null);}
 private UUID account(){UUID id=UUID.randomUUID();jdbc.update("insert into user_account(id,tenant_id,login_name,display_name) values(?,?,?,'本地测试')",id,T,id.toString());return id;}
 private void as(UUID actor,String... permission){as(actor,Set.of(hotel),permission);}private void as(UUID actor,Set<UUID> scopes,String... permission){TenantContext.set(new TenantPrincipal(T,actor,"FINANCE_TEST",Set.of("FINANCE_TEST"),Set.of(permission),scopes,Set.of(),false,UUID.randomUUID()));}
 private static <R> R call(Supplier<R> body){return tx.execute(status->{jdbc.execute("set local role hotel_ai_os_app");return body.get();});}
}
